/* Dump the sound-effect cue list (generated by the scenes) to timing/sfx.json */
const { chromium } = require('playwright');
const path = require('path'), fs = require('fs');
(async () => {
  const root = path.resolve(__dirname, '..');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1080, height: 1920 } });
  page.on('pageerror', e => console.log('[pageerror]', e.message));
  await page.goto('file://' + path.join(root, 'src/index.html'));
  await page.waitForFunction(() => window.READY === true, null, { timeout: 15000 });
  const data = await page.evaluate(() => ({ sfx: window.SFX.slice().sort((a, b) => a.t - b.t), cuts: window.CUTS, duration: window.DURATION }));
  fs.writeFileSync(path.join(root, 'timing/sfx.json'), JSON.stringify(data, null, 1));
  const n = {}; for (const e of data.sfx) n[e.type] = (n[e.type] || 0) + 1;
  console.log('sfx events:', data.sfx.length, JSON.stringify(n), 'duration', data.duration);
  await browser.close();
})();
